// A native Chromium lossless WebP fixture. Its four pixels include
// translucent alpha and were decoded with WebCodecs before being committed.

const LOSSLESS_WEBP_BASE64 =
  "";

export const losslessWebp = Uint8Array.from(
  atob(LOSSLESS_WEBP_BASE64),
  (character) => character.charCodeAt(0),
);

export function webp(): Uint8Array {
  return new Uint8Array(losslessWebp);
}

export const corruptWebp = new Uint8Array([
  82, 73, 70, 70, 18, 0, 0, 0, 87, 69, 66, 80, 86, 80, 56, 76, 5, 0, 0,
  0, 0, 0, 0, 0, 0, 0,
]);
